CREATE FUNCTION pg_temp.cpm_build(p_row JSONB) RETURNS TEXT LANGUAGE SQL AS $$
 SELECT internal.build_initial_cpm_admitted_manifest(jsonb_populate_record(NULL::internal.initial_preparation_admission_receipts,p_row),
  (SELECT (v->>'authorized_at_ms')::BIGINT FROM cpm_proof_fixture));
$$;
CREATE FUNCTION pg_temp.cpm_validate(p_row JSONB) RETURNS TEXT LANGUAGE SQL AS $$
 SELECT internal.validate_initial_cpm_admitted_proof(jsonb_populate_record(NULL::internal.initial_preparation_admission_receipts,p_row));
$$;
SELECT extensions.is(pg_temp.cpm_build(v->'receipt'),v#>>'{receipt,manifest}','manifest equals independent Python golden bytes') FROM cpm_proof_fixture;
SELECT extensions.is(pg_temp.cpm_validate(v->'receipt'),v#>>'{receipt,receipt_digest}','receipt digest equals independent Python golden digest') FROM cpm_proof_fixture;
SELECT extensions.is(pg_temp.cpm_validate(v#>'{two_photo,receipt}'),v#>>'{two_photo,receipt,receipt_digest}',
 'two-photo six-role receipt equals independent golden digest') FROM cpm_proof_fixture;
CREATE TEMP TABLE cpm_member_images AS
 SELECT fixture.name,fixture.receipt,image.* FROM cpm_proof_fixture
 CROSS JOIN LATERAL (VALUES ('one_photo',v->'receipt'),('two_photo',v#>'{two_photo,receipt}')) fixture(name,receipt)
 CROSS JOIN LATERAL internal.initial_admission_member_images(
  jsonb_populate_record(NULL::internal.initial_preparation_admission_receipts,fixture.receipt)) image;
SELECT extensions.is(array_agg(statement_key ORDER BY statement_key COLLATE "C"),
 ARRAY['CPM.capacity.update','Finalizer.admission.insert','Finalizer.submission.insert','Handoff.receipt.insert','Lifecycle.pending.insert'],
 name||': admission retains original cohort without M1 copies') FROM cpm_member_images GROUP BY name;
SELECT extensions.is(new_image,(receipt->'cpm_capacity_predecessor')||jsonb_build_object('state','admitted'),
 name||': retained capacity preserves original owner, bytes and write liability')
 FROM cpm_member_images WHERE statement_key='CPM.capacity.update';
SELECT extensions.is(new_image->>'input_schema_version','2',name||': CPM submission uses encoded-context schema')
 FROM cpm_member_images WHERE statement_key='Finalizer.submission.insert';
SELECT extensions.is(new_image->'ordered_descriptions',(receipt->>'input')::JSONB->'contexts',
 name||': submitted contexts stay exact and ordered') FROM cpm_member_images WHERE statement_key='Finalizer.submission.insert';
SELECT extensions.is(new_image->>'canonical_input',receipt->>'input',name||': canonical input bytes survive materialization projection')
 FROM cpm_member_images WHERE statement_key='Finalizer.admission.insert';
SELECT extensions.is(new_image->>'binding_version','4',name||': admission binds CPM content')
 FROM cpm_member_images WHERE statement_key='Finalizer.admission.insert';
