SET LOCAL TIME ZONE 'UTC';
-- Recommit changed canonical components so rejection tests semantic bindings,
-- rather than merely relying on their old manifest references.
CREATE FUNCTION pg_temp.cpm_change(p_component TEXT,p_path TEXT[],p_value JSONB) RETURNS TEXT LANGUAGE plpgsql AS $$
DECLARE r JSONB; changed JSONB; verified JSONB;
BEGIN
 SELECT v->'receipt' INTO r FROM cpm_proof_fixture;
 changed:=jsonb_set((r->>p_component)::JSONB,p_path,p_value);
 r:=jsonb_set(r,ARRAY[p_component],to_jsonb(internal.initial_canonical(changed)));
 IF p_component='cpm_retained_roles' THEN
  verified:=(r->>'cpm_verification')::JSONB||jsonb_build_object('snapshot_digest',encode(extensions.digest(convert_to(
   'merian.initial-analysis.cpm-verification-start.v1'||E'\n'||(r->>'cpm_retained_roles'),'UTF8'),'sha256'),'hex'));
  r:=jsonb_set(r,'{cpm_verification}',to_jsonb(internal.initial_canonical(verified)));
 END IF;
 r:=jsonb_set(r,'{cpm_verification_digest}',to_jsonb(encode(extensions.digest(convert_to(
  'merian.initial-analysis.cpm-photo-verification.v1'||E'\n'||(r->>'cpm_verification'),'UTF8'),'sha256'),'hex')));
 RETURN pg_temp.cpm_build(r);
END; $$;
