-- Synthetic immutable-proof/prestate projections only. No successful admission
-- or cancellation is claimed by these cases while storage stays closed.
CREATE TEMP TABLE cpm_c1_images AS SELECT f.name,f.receipt,
 internal.initial_cpm_cancellation_retained_images(jsonb_populate_record(NULL::internal.initial_preparation_admission_receipts,f.receipt),FALSE) before_image,
 internal.initial_cpm_cancellation_retained_images(jsonb_populate_record(NULL::internal.initial_preparation_admission_receipts,f.receipt),TRUE) after_image
 FROM cpm_proof_fixture CROSS JOIN LATERAL (VALUES ('one_photo',v->'receipt'),('two_photo',v#>'{two_photo,receipt}')) f(name,receipt);
SELECT extensions.is(before_image->'capacity',after_image->'capacity',name||': cancellation cannot release retained bytes') FROM cpm_c1_images;
SELECT extensions.is(before_image->'closures',after_image->'closures',name||': cancellation preserves original live closure evidence') FROM cpm_c1_images;
SELECT extensions.is((SELECT jsonb_agg(e||jsonb_build_object('retired',TRUE) ORDER BY e->>'object_id') FROM jsonb_array_elements(before_image->'attempts') e),
 after_image->'attempts',name||': cancellation changes only attempt retirement') FROM cpm_c1_images;
CREATE TEMP TABLE cpm_c1_prestate AS SELECT name,jsonb_build_object('scan_id',receipt->'scan_id','owner_id',receipt->'owner_id',
 'admission_receipt_id',receipt->'admission_receipt_id','admission_receipt_digest',receipt->'receipt_digest',
 'private_components',jsonb_build_object('receipt',receipt,'admission',jsonb_build_object('binding_version',4)),
 'cpm_retained',before_image,'media_fence',NULL,'media_cohort',NULL,'destination_registry','[]'::JSONB,
 'erasure_images',(SELECT jsonb_object_agg(relation_name,'[]'::JSONB) FROM internal.initial_cancellation_private_catalog())) value
 FROM cpm_c1_images;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_cpm_cancellation_empty_destination(%L::UUID,%L::JSONB)',value->>'scan_id',value),
